// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as handler } from "../.open-next/worker.js";
import { type RateLimiter, rateLimitApi } from "../src/lib/rate-limit/api-rate-limit";

interface Env {
  API_RATE_LIMITER: RateLimiter;
}

/** Applies the per-IP /api/* limit before the OpenNext handler sees the request. */
export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const limited = await rateLimitApi(request, env.API_RATE_LIMITER);
    return limited ?? handler.fetch(request, env, ctx);
  },
};
